ALTER TABLE "CollectionRun" ADD COLUMN "readPlan" JSONB, ADD COLUMN "capturedPosts" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "capturedCommentsCount" INTEGER NOT NULL DEFAULT 0;
CREATE TABLE "SemanticControl" ("configId" TEXT PRIMARY KEY REFERENCES "CollectionConfig"("id") ON DELETE CASCADE ON UPDATE CASCADE, "enabled" BOOLEAN NOT NULL DEFAULT false, "version" INTEGER NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CapturedPost" ("id" TEXT PRIMARY KEY, "configId" TEXT NOT NULL REFERENCES "CollectionConfig"("id") ON DELETE CASCADE ON UPDATE CASCADE, "runId" TEXT NOT NULL REFERENCES "CollectionRun"("id") ON DELETE CASCADE ON UPDATE CASCADE, "platformPostId" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "snapshot" JSONB NOT NULL, "coverage" TEXT NOT NULL DEFAULT 'UNKNOWN', "stopReason" TEXT, "lastRunId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "CapturedPost_configId_platformPostId_contentHash_key" ON "CapturedPost"("configId","platformPostId","contentHash");
CREATE TABLE "CapturedComment" ("id" TEXT PRIMARY KEY, "configId" TEXT NOT NULL REFERENCES "CollectionConfig"("id") ON DELETE CASCADE ON UPDATE CASCADE, "runId" TEXT NOT NULL REFERENCES "CollectionRun"("id") ON DELETE CASCADE ON UPDATE CASCADE, "postId" TEXT NOT NULL REFERENCES "CapturedPost"("id") ON DELETE CASCADE ON UPDATE CASCADE, "platformCommentId" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "contextVersion" TEXT NOT NULL, "snapshot" JSONB NOT NULL, "isDemo" BOOLEAN NOT NULL, "lastRunId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "CapturedComment_content_version_key" ON "CapturedComment"("configId","platformCommentId","contentHash","contextVersion");
CREATE INDEX "CapturedComment_configId_createdAt_idx" ON "CapturedComment"("configId","createdAt");
ALTER TABLE "SemanticReview" ADD COLUMN "analysisKey" TEXT, ADD COLUMN "selectedModel" TEXT, ADD COLUMN "ruleHash" TEXT, ADD COLUMN "contextVersion" TEXT, ADD COLUMN "captureId" TEXT REFERENCES "CapturedComment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "SemanticReview_analysisKey_key" ON "SemanticReview"("analysisKey");
